import{_ as t,o as h,c as a,a2 as i}from"./chunks/framework.BBd5PKnH.js";const r="/dev-notes/assets/fig7-jackie-kennedy-onassis.tjpcGqjx.svg",o="/dev-notes/assets/fig8-pablo-picasso.Dn1g0iPM.svg",g="/dev-notes/assets/fig7a-axes.DWuYpgr_.svg",s="/dev-notes/assets/fig8a-axes.WLa2svr5.svg",c="/dev-notes/assets/fig7b-phase.CFQcRjgC.svg",e="/dev-notes/assets/fig8b-phase.BhcnbsVb.svg",d="/dev-notes/assets/fig7c-quadrants.D-juY5gk.svg",u="/dev-notes/assets/fig8c-quadrants.BZUXp20_.svg",y=JSON.parse('{"title":"Example Charts: Jacqueline Kennedy Onassis và Pablo Picasso","description":"","frontmatter":{},"headers":[],"relativePath":"astro/charts/example-charts-note/example-charts-jackie-picasso.md","filePath":"astro/charts/example-charts-note/example-charts-jackie-picasso.md"}'),l={name:"astro/charts/example-charts-note/example-charts-jackie-picasso.md"};function m(p,n,b,q,k,v){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="example-charts-jacqueline-kennedy-onassis-va-pablo-picasso" tabindex="-1">Example Charts: Jacqueline Kennedy Onassis và Pablo Picasso <a class="header-anchor" href="#example-charts-jacqueline-kennedy-onassis-va-pablo-picasso" aria-label="Permalink to &quot;Example Charts: Jacqueline Kennedy Onassis và Pablo Picasso&quot;">​</a></h1><p><em>(Demetra George, Ancient Astrology in Theory and Practice Vol. I, trang 67, Figure 7 và 8. Ngay sau Chương 5 &quot;Gender of the Planets&quot;)</em></p><p>Quy ước: <strong>[Sách]</strong> = nội dung có trong trang sách. <strong>[Bổ sung]</strong> = mình tự tính, diễn giải hoặc lấy từ các note trước. Phần [Bổ sung] không phải lời tác giả, hãy đối chiếu lại với sách.</p><hr><h2 id="_0-tom-tat-nhanh" tabindex="-1">0. Tóm tắt nhanh <a class="header-anchor" href="#_0-tom-tat-nhanh" aria-label="Permalink to &quot;0. Tóm tắt nhanh&quot;">​</a></h2><ul><li>Trang này là <strong>ví dụ áp dụng Chương 5</strong>. Trong trang này sách chỉ bình luận về <strong>giới tính của cung (sign)</strong>. [Bổ sung] Mình đoán lý do là cung được coi là điều kiện quan trọng nhất trong 4 điều kiện của Chương 5.</li><li><strong>Jackie</strong> có 3 trong 7 hành tinh &quot;ngược giới tính với cung&quot;. Đó là Moon, Venus (nữ trong cung nam) và Mars (nam trong cung nữ).</li><li><strong>Picasso</strong> có <strong>cả 7 hành tinh</strong> nằm trong cung ngược giới tính tự nhiên. Đây là điểm sách nhấn mạnh.</li><li>Sách nói hai lá số này sẽ được dùng xuyên suốt phần còn lại của cuốn sách.</li><li>Mình dùng <strong>whole sign</strong> như đã thống nhất, và sách cũng ghi rõ &quot;Geocentric, Tropical, Whole Sign, True Node&quot; ở caption.</li></ul><hr><h2 id="_1-dich-đoan-sach-trang-67" tabindex="-1">1. Dịch đoạn sách (trang 67) <a class="header-anchor" href="#_1-dich-đoan-sach-trang-67" aria-label="Permalink to &quot;1. Dịch đoạn sách (trang 67)&quot;">​</a></h2><p><strong>[Sách] Jackie Kennedy Onassis</strong></p><ul><li>Sun (nam) ở Leo (cung nam). Moon (nữ) ở Aries (cung nam).</li><li>Mercury ở <strong>morning phase</strong> trong Leo.</li><li>Venus (nữ) ở Gemini (cung nam). Mars (nam) ở Virgo (cung nữ). Jupiter (nam) ở Gemini (cung nam). Saturn (nam) ở Sagittarius (cung nam).</li><li>Hai hành tinh nữ đều ở cung nam. Điều này đẩy họ về phía <strong>hoạt động nhiều hơn</strong>, có thể đến mức căng thẳng vì làm quá sức, hoặc khó bộc lộ sự mong manh và khó nhận giúp đỡ.</li><li>Mars ở Virgo (cung nữ) thì xung lực bốc đồng của Mars bị <strong>làm chậm lại bằng sự phân biệt, phân tích</strong>.</li></ul><p><strong>[Sách] Picasso</strong></p><ul><li>Mọi hành tinh đều nằm trong cung <strong>đối lập với giới tính tự nhiên</strong> của nó.</li><li>Gợi ý một sự <strong>khó chịu về năng lượng ngay trong chính cơ thể mình</strong>: được bảo &quot;đi chậm&quot; khi xung lực là nhanh, và ngược lại.</li><li>Cũng có thể chỉ một cách biểu đạt giới tính <strong>không phân cực thành khuôn mẫu nam/nữ</strong>.</li></ul><blockquote><p>Lưu ý: đây là bản dịch ý của mình, không phải bản dịch từng chữ.</p></blockquote><hr><h2 id="_2-hai-la-so-ve-lai-whole-sign" tabindex="-1">2. Hai lá số vẽ lại (whole sign) <a class="header-anchor" href="#_2-hai-la-so-ve-lai-whole-sign" aria-label="Permalink to &quot;2. Hai lá số vẽ lại (whole sign)&quot;">​</a></h2><h3 id="figure-7-jacqueline-kennedy-onassis" tabindex="-1">Figure 7. Jacqueline Kennedy Onassis <a class="header-anchor" href="#figure-7-jacqueline-kennedy-onassis" aria-label="Permalink to &quot;Figure 7. Jacqueline Kennedy Onassis&quot;">​</a></h3><p><img src="'+r+'" alt="Jackie"></p><p>Dữ liệu đọc từ hình: Asc 17°58&#39; Scorpio, MC 28°54&#39; Leo. <strong>Lá số ngày</strong> (Sun ở nhà 10, trên đường chân trời).</p><h3 id="figure-8-pablo-picasso" tabindex="-1">Figure 8. Pablo Picasso <a class="header-anchor" href="#figure-8-pablo-picasso" aria-label="Permalink to &quot;Figure 8. Pablo Picasso&quot;">​</a></h3><p><img src="'+o+'" alt="Picasso"></p><p>Dữ liệu đọc từ hình: Asc 5°38&#39; Leo, MC 25°04&#39; Aries. <strong>Lá số đêm</strong> (Sun ở nhà 4, dưới đường chân trời).</p><h3 id="cach-đoc-hinh" tabindex="-1">Cách đọc hình <a class="header-anchor" href="#cach-đoc-hinh" aria-label="Permalink to &quot;Cách đọc hình&quot;">​</a></h3><ul><li>Nhà 1 bắt đầu ở bên trái, các nhà (1 → 12) đi <strong>ngược chiều kim đồng hồ</strong>. Mỗi nhà là cả một cung (whole sign). Đường <strong>Asc nằm bên trong nhà 1</strong> (không nằm ở ranh giới), đúng theo vị trí độ thật.</li><li>Chấm màu là <strong>vị trí thật</strong> trên vòng tròn. Chữ là nhãn, được đẩy ra một chút cho khỏi chồng nhau, nối bằng đường mảnh.</li><li>℞ = retrograde. ☊/☋ = nút Bắc/Nam. ⊗ = Part of Fortune.</li><li><strong>[Bổ sung] Lưu ý whole sign:</strong> MC không nằm ở &quot;đầu nhà 10&quot;. Ở Picasso, <strong>MC 25° Aries nằm trong nhà 9</strong>, còn nhà 10 là cả cung Taurus. Ở Jackie, MC rơi vào nhà 10 (Leo). Đây chính là điều mình đã giải thích ở note về cusp: trục Asc/MC nằm <em>bên trong</em> nhà chứ không phải ranh giới nhà.</li></ul><p>Kiểm tra số liệu: Part of Fortune mình tính ra khớp với sách (Jackie 8°25&#39; Leo vs sách 8°24&#39;; Picasso 0°08&#39; Cancer vs sách 0°07&#39;). Chênh 1&#39; là do làm tròn. Điều này cho thấy dữ liệu mình đọc từ hình khá chắc.</p><hr><h2 id="_2b-ba-khai-niem-đoc-hinh-truc-morning-evening-quadrant" tabindex="-1">2b. Ba khái niệm đọc hình: trục, morning/evening, quadrant <a class="header-anchor" href="#_2b-ba-khai-niem-đoc-hinh-truc-morning-evening-quadrant" aria-label="Permalink to &quot;2b. Ba khái niệm đọc hình: trục, morning/evening, quadrant&quot;">​</a></h2><h3 id="_1-vi-sao-asc–dsc-va-mc–ic-khong-vuong-goc" tabindex="-1">(1) Vì sao ASC–DSC và MC–IC không vuông góc? <a class="header-anchor" href="#_1-vi-sao-asc–dsc-va-mc–ic-khong-vuong-goc" aria-label="Permalink to &quot;(1) Vì sao ASC–DSC và MC–IC không vuông góc?&quot;">​</a></h3><ul><li>ASC–DSC luôn thẳng hàng (180°). MC–IC cũng vậy.</li><li><strong>ASC–MC không bắt buộc là 90°.</strong> Đường chân trời và đường kinh tuyến vuông góc nhau trên bầu trời, nhưng vòng hoàng đạo nghiêng khoảng 23° nên khi trải thành vòng tròn 360°, khoảng cách ASC–MC thay đổi theo giờ và nơi sinh. Đây là bình thường, không phải lỗi vẽ.</li><li>Kennedy: 4 khoảng giữa các trục là 101° / 79° / 101° / 79°. Picasso: 79° / 101° / 79° / 101°.</li></ul><p><strong>Kennedy: Hình A</strong><img src="'+g+'" alt="Kennedy A"></p><p><strong>Picasso: Hình A</strong><img src="'+s+'" alt="Picasso A"></p><h3 id="_2-morning-evening" tabindex="-1">(2) Morning / evening <a class="header-anchor" href="#_2-morning-evening" aria-label="Permalink to &quot;(2) Morning / evening&quot;">​</a></h3><p>So từng hành tinh với <strong>Sun</strong> trên vòng hoàng đạo:</p><ul><li><strong>Morning</strong> = kinh độ <strong>nhỏ hơn</strong> Sun (tối đa 180°). Hành tinh mọc <strong>trước</strong> Sun, thấy trước bình minh. Vùng <strong>xanh</strong> trong hình, <strong>nam hóa</strong>.</li><li><strong>Evening</strong> = kinh độ <strong>lớn hơn</strong> Sun. Hành tinh mọc <strong>sau</strong> Sun, thấy lúc chiều tối. Vùng <strong>hồng</strong>, <strong>nữ hóa</strong>.</li><li>Vạch đứt = mốc <strong>15°</strong> và <strong>120°</strong> cách Sun (phần tinh chỉnh nâng cao của sách). Quy tắc cơ bản chỉ cần xem hành tinh ở bên xanh hay bên hồng.</li></ul><table tabindex="0"><thead><tr><th>Kennedy</th><th>Phase</th><th>Picasso</th><th>Phase</th></tr></thead><tbody><tr><td>Mercury</td><td>morning 3°</td><td>Venus</td><td>morning 28°</td></tr><tr><td>Venus</td><td>morning 43°</td><td>Mars</td><td>morning 110°</td></tr><tr><td>Jupiter</td><td>morning 56°</td><td>Jupiter ℞</td><td>morning 159° (ngoài 120°)</td></tr><tr><td>Moon</td><td>morning 100°</td><td>Saturn ℞</td><td>morning 173° (ngoài 120°)</td></tr><tr><td>Mars</td><td>evening 40°</td><td>Mercury</td><td>evening 22°</td></tr><tr><td>Saturn ℞</td><td>evening 140° (ngoài 120°)</td><td>Moon</td><td>evening 36°</td></tr></tbody></table><p>Mercury của Kennedy cách Sun chỉ 3° nhưng vẫn ở bên xanh, nên sách gọi là &quot;morning-phase Mercury&quot;. Với Picasso, Saturn cách Sun 173°, chỉ cách ranh giới xanh/hồng khoảng 7° nhưng vẫn thuộc morning. Jupiter và Saturn của Picasso đều retrograde, điều bình thường khi hành tinh ở gần đối diện Sun.</p><p><strong>Kennedy: Hình B</strong><img src="'+c+'" alt="Kennedy B"></p><p><strong>Picasso: Hình B</strong><img src="'+e+'" alt="Picasso B"></p><h3 id="_3-quadrant-theo-nha-va-theo-đo" tabindex="-1">(3) Quadrant &quot;theo nhà&quot; và &quot;theo độ&quot; <a class="header-anchor" href="#_3-quadrant-theo-nha-va-theo-đo" aria-label="Permalink to &quot;(3) Quadrant &quot;theo nhà&quot; và &quot;theo độ&quot;&quot;">​</a></h3><p>Hai trục chia lá số thành 4 góc phần tư. Theo sách (Bảng 7): ASC→MC và DSC→IC là <strong>nam</strong>, MC→DSC và IC→ASC là <strong>nữ</strong>. Có hai cách xác định hành tinh nằm ở quadrant nào:</p><ul><li><strong>Theo nhà (vòng số nhà ngoài cùng):</strong> nhà 10–12 và 4–6 là nam, nhà 1–3 và 7–9 là nữ. Mỗi quadrant đúng 90°.</li><li><strong>Theo độ (vùng tô bên trong):</strong> dùng chính đường ASC/MC/DSC/IC thật làm ranh giới nên quadrant rộng 79° hoặc 101°. Paulus dùng cách này. Sách nói chưa rõ nên chọn cách nào.</li></ul><p>Hai cách chỉ khác nhau với hành tinh nằm gần trục:</p><ul><li><strong>Kennedy:</strong> Sun ở nhà 10 (nam theo nhà) nhưng đã vượt MC khoảng 24° nên theo độ thuộc quadrant nữ. Mercury cũng vậy. Hai hành tinh này có chữ đỏ trong Hình C.</li><li><strong>Picasso:</strong> hai cách cho kết quả giống nhau ở cả 7 hành tinh. Venus ở quadrant nữ (nhà 3), sáu hành tinh còn lại ở quadrant nam. Sun cách IC khoảng 7.6° nhưng vẫn cùng quadrant với nhà 4.</li></ul><p><strong>Kennedy: Hình C</strong><img src="'+d+'" alt="Kennedy C"></p><p><strong>Picasso: Hình C</strong><img src="'+u+'" alt="Picasso C"></p><hr><h2 id="_3-bang-du-kien-đa-tinh" tabindex="-1">3. Bảng dữ kiện (đã tính) <a class="header-anchor" href="#_3-bang-du-kien-đa-tinh" aria-label="Permalink to &quot;3. Bảng dữ kiện (đã tính)&quot;">​</a></h2><p>Cách đọc cột:</p><ul><li><strong>Cung gender</strong>: cung lửa/khí là nam (M), đất/nước là nữ (F).</li><li><strong>Phase</strong>: <em>morning</em> = đi trước Sun (kinh độ nhỏ hơn Sun), <em>evening</em> = đi sau Sun. Số trong ngoặc là số độ cách Sun.</li><li><strong>Quadrant nhà / độ</strong>: quadrant theo nhà whole sign, và quadrant theo độ chính xác (sách nói chưa rõ nên dùng cách nào, Paulus dùng độ).</li><li>Cột latitude <strong>bỏ trống</strong>: hình không cho vĩ độ thiên cầu (celestial latitude), nên điều kiện thứ 4 không đánh giá được.</li></ul><h3 id="jackie-la-so-ngay" tabindex="-1">Jackie (lá số ngày) <a class="header-anchor" href="#jackie-la-so-ngay" aria-label="Permalink to &quot;Jackie (lá số ngày)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Vị trí</th><th>Nhà</th><th>Giới tính tự nhiên</th><th>Cung</th><th>Phase</th><th>Quadrant nhà / độ</th></tr></thead><tbody><tr><td>Sun ☉</td><td>5°09&#39; Leo</td><td>10</td><td>M</td><td>M</td><td>(mốc)</td><td>M / <strong>F</strong></td></tr><tr><td>Moon ☽</td><td>25°36&#39; Aries</td><td>6</td><td><strong>F</strong></td><td>M</td><td>morning (99.6°)</td><td>M / M</td></tr><tr><td>Mercury ☿</td><td>2°24&#39; Leo</td><td>10</td><td>M (common)</td><td>M</td><td>morning (2.8°)</td><td>M / <strong>F</strong></td></tr><tr><td>Venus ♀</td><td>21°46&#39; Gemini</td><td>8</td><td><strong>F</strong></td><td>M</td><td>morning (43.4°)</td><td>F / F</td></tr><tr><td>Mars ♂</td><td>14°49&#39; Virgo</td><td>11</td><td>M</td><td><strong>F</strong></td><td>evening (39.7°)</td><td>M / M</td></tr><tr><td>Jupiter ♃</td><td>9°14&#39; Gemini</td><td>8</td><td>M</td><td>M</td><td>morning (55.9°)</td><td>F / F</td></tr><tr><td>Saturn ♄ ℞</td><td>24°39&#39; Sagittarius</td><td>2</td><td>M</td><td>M</td><td>evening (139.5°)</td><td>F / F</td></tr></tbody></table><h3 id="picasso-la-so-đem" tabindex="-1">Picasso (lá số đêm) <a class="header-anchor" href="#picasso-la-so-đem" aria-label="Permalink to &quot;Picasso (lá số đêm)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Vị trí</th><th>Nhà</th><th>Giới tính tự nhiên</th><th>Cung</th><th>Phase</th><th>Quadrant nhà / độ</th></tr></thead><tbody><tr><td>Sun ☉</td><td>2°42&#39; Scorpio</td><td>4</td><td>M</td><td><strong>F</strong></td><td>(mốc)</td><td>M / M</td></tr><tr><td>Moon ☽</td><td>8°12&#39; Sagittarius</td><td>5</td><td><strong>F</strong></td><td>M</td><td>evening (35.5°)</td><td>M / M</td></tr><tr><td>Mercury ☿</td><td>24°14&#39; Scorpio</td><td>4</td><td>M (common)</td><td><strong>F</strong></td><td>evening (21.5°)</td><td>M / M</td></tr><tr><td>Venus ♀</td><td>4°31&#39; Libra</td><td>3</td><td><strong>F</strong></td><td>M</td><td>morning (28.2°)</td><td>F / F</td></tr><tr><td>Mars ♂</td><td>12°21&#39; Cancer</td><td>12</td><td>M</td><td><strong>F</strong></td><td>morning (110.3°)</td><td>M / M</td></tr><tr><td>Jupiter ♃ ℞</td><td>23°33&#39; Taurus</td><td>10</td><td>M</td><td><strong>F</strong></td><td>morning (159.1°)</td><td>M / M</td></tr><tr><td>Saturn ♄ ℞</td><td>9°27&#39; Taurus</td><td>10</td><td>M</td><td><strong>F</strong></td><td>morning (173.2°)</td><td>M / M</td></tr></tbody></table><p>In đậm ở cột &quot;Cung&quot; nghĩa là <strong>cung ngược giới tính tự nhiên</strong>. Đếm nhanh: Jackie 3/7, Picasso 7/7.</p><hr><h2 id="_4-vi-sao-co-cho-m-f-khac-nhau-giua-nha-va-đo" tabindex="-1">4. Vì sao có chỗ M/F khác nhau giữa &quot;nhà&quot; và &quot;độ&quot;? <a class="header-anchor" href="#_4-vi-sao-co-cho-m-f-khac-nhau-giua-nha-va-đo" aria-label="Permalink to &quot;4. Vì sao có chỗ M/F khác nhau giữa &quot;nhà&quot; và &quot;độ&quot;?&quot;">​</a></h2><p>Ví dụ <strong>Sun của Jackie</strong>: ở cung Leo, cả cung này là nhà 10. Whole sign xếp nó vào quadrant nam (Asc → MC). Nhưng MC ở 28°54&#39; Leo còn Sun ở 5°09&#39; Leo, tức Sun <strong>đã qua đỉnh trời ~24°</strong>, nên theo độ chính xác nó đã sang quadrant nữ (MC → Dsc).</p><p>→ Đây chính là chỗ sách nói &quot;chưa rõ dùng whole sign hay độ&quot;. Hai cách cho kết quả khác nhau ở những hành tinh nằm gần trục. Với hai lá số này, Sun và Mercury của Jackie là hai trường hợp như vậy. Mình giữ cả hai cột để bạn thấy.</p><hr><h2 id="_5-đoc-gioi-tinh-tung-hanh-tinh-ap-dung-bang-7-va-8" tabindex="-1">5. Đọc giới tính từng hành tinh (áp dụng Bảng 7 và 8) <a class="header-anchor" href="#_5-đoc-gioi-tinh-tung-hanh-tinh-ap-dung-bang-7-va-8" aria-label="Permalink to &quot;5. Đọc giới tính từng hành tinh (áp dụng Bảng 7 và 8)&quot;">​</a></h2><p><strong>[Bổ sung] Cách làm của mình, không phải công thức của sách.</strong> Sách không cho công thức cộng điểm. Mình chỉ đếm xem mỗi điều kiện đẩy về nam (+) hay nữ (−), rồi nhớ rằng <strong>cung là điều kiện quan trọng nhất</strong>. Kết quả là gợi ý, không phải đáp án chuẩn.</p><h3 id="jackie" tabindex="-1">Jackie <a class="header-anchor" href="#jackie" aria-label="Permalink to &quot;Jackie&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Cung</th><th>Phase</th><th>Quadrant (nhà/độ)</th><th>Đọc ra</th></tr></thead><tbody><tr><td>Sun (M)</td><td>+</td><td>–</td><td>+ / −</td><td><strong>Nam</strong>, quadrant ở rìa</td></tr><tr><td>Moon (F)</td><td>+ (nam hóa)</td><td>+ (morning)</td><td>+ / +</td><td><strong>Nữ bị nam hóa</strong> (đầu &quot;masculinized feminine&quot;)</td></tr><tr><td>Mercury (M)</td><td>+</td><td>+</td><td>+ / −</td><td><strong>Nam</strong> đến rất nam</td></tr><tr><td>Venus (F)</td><td>+ (nam hóa)</td><td>+ (morning)</td><td>− / −</td><td><strong>Nữ bị nam hóa</strong>, nhưng quadrant kéo lại</td></tr><tr><td>Mars (M)</td><td>− (nữ hóa)</td><td>− (evening)</td><td>+ / +</td><td><strong>Nam bị nữ hóa</strong>, quadrant giữ lại một phần</td></tr><tr><td>Jupiter (M)</td><td>+</td><td>+</td><td>− / −</td><td><strong>Nam</strong></td></tr><tr><td>Saturn (M) ℞</td><td>+</td><td>? (139.5°, ngoài vùng 15–120°)</td><td>− / −</td><td><strong>Nam</strong>, có kéo về phía nữ</td></tr></tbody></table><p><strong>Điểm đáng chú ý:</strong></p><ul><li><strong>Moon và Venus</strong> đều nam hóa. Khớp với câu sách: hai hành tinh nữ cùng bị đẩy về phía hoạt động, nên có xu hướng &quot;làm quá, khó cho mình yếu mềm&quot;.</li><li><strong>Mars</strong> bị cung Virgo nữ hóa và cả phase evening nữ hóa. Khớp với sách: xung lực bị phân tích làm chậm lại.</li><li>Mars còn là <strong>chủ tinh của Asc</strong> (Asc Scorpio, ruler cổ điển là Mars). Một hành tinh quan trọng như vậy đang ở trạng thái &quot;nam bị làm chậm&quot; nên cách diễn đạt bản thân (Asc) mang sắc thái này.</li></ul><h3 id="picasso" tabindex="-1">Picasso <a class="header-anchor" href="#picasso" aria-label="Permalink to &quot;Picasso&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Cung</th><th>Phase</th><th>Quadrant (nhà/độ)</th><th>Đọc ra</th></tr></thead><tbody><tr><td>Sun (M)</td><td>− (nữ hóa)</td><td>–</td><td>+ / +</td><td><strong>Nam bị nữ hóa</strong> nhẹ (quadrant giữ lại)</td></tr><tr><td>Moon (F)</td><td>+ (nam hóa)</td><td>− (evening)</td><td>+ / +</td><td><strong>Nữ bị nam hóa</strong></td></tr><tr><td>Mercury (M)</td><td>−</td><td>− (evening)</td><td>+ / +</td><td><strong>Nam bị nữ hóa</strong></td></tr><tr><td>Venus (F)</td><td>+ (nam hóa)</td><td>+ (morning)</td><td>− / −</td><td><strong>Nữ bị nam hóa</strong>, quadrant kéo lại</td></tr><tr><td>Mars (M)</td><td>−</td><td>+ (morning, 110°)</td><td>+ / +</td><td>Nam bị nữ hóa → nam (cung nặng nhất, quadrant + phase kéo ngược)</td></tr><tr><td>Jupiter (M) ℞</td><td>−</td><td>? (159°, ngoài vùng)</td><td>+ / +</td><td>Nam bị nữ hóa → nam</td></tr><tr><td>Saturn (M) ℞</td><td>−</td><td>? (173°, ngoài vùng)</td><td>+ / +</td><td>Nam bị nữ hóa → nam</td></tr></tbody></table><p><strong>Ý nghĩa của &quot;cả 7 đều ngược&quot;:</strong></p><ul><li>Lá số này là một trường hợp <strong>cực đoan về mặt cung</strong>. Mọi hành tinh nam đều ở cung nữ (bị làm chậm/mềm), mọi hành tinh nữ đều ở cung nam (bị đẩy nhanh/cứng).</li><li>Nhưng ở các điều kiện khác (quadrant, phase) vẫn có hành tinh bị kéo ngược lại. Vì vậy, &quot;ngược 100% ở cung&quot; không có nghĩa &quot;ngược 100% ở mọi điều kiện&quot;. <strong>[Bổ sung]</strong> Cũng đừng đọc quá lố: tổng thể phụ thuộc cách bạn cân trọng số.</li><li>Sách đề xuất hai cách đọc cùng lúc: một là <strong>cảm giác không thoải mái trong cơ thể/năng lượng</strong> (nhịp nhanh chậm bị ngược), hai là <strong>cách biểu đạt không theo khuôn mẫu nam/nữ</strong>. Hai cách này không loại trừ nhau.</li></ul><h3 id="hai-la-so-hai-kieu-lech" tabindex="-1">Hai lá số, hai kiểu &quot;lệch&quot; <a class="header-anchor" href="#hai-la-so-hai-kieu-lech" aria-label="Permalink to &quot;Hai lá số, hai kiểu &quot;lệch&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Jackie</th><th>Picasso</th></tr></thead><tbody><tr><td>Số hành tinh ngược cung</td><td>3/7</td><td>7/7</td></tr><tr><td>Dạng lệch</td><td>Chọn lọc: nữ → nam hóa, một Mars bị làm chậm</td><td>Toàn diện, ở cấp cung</td></tr><tr><td>Sách đọc</td><td>Hoạt động quá mức; khó nhận giúp; Mars được phân tích điều tiết</td><td>Khó chịu về nhịp năng lượng; không phân cực khuôn mẫu</td></tr></tbody></table><hr><h2 id="_6-đoc-them-bang-5-lop-celestial-condition" tabindex="-1">6. Đọc thêm bằng &quot;5 lớp&quot; (celestial condition) <a class="header-anchor" href="#_6-đoc-them-bang-5-lop-celestial-condition" aria-label="Permalink to &quot;6. Đọc thêm bằng &quot;5 lớp&quot; (celestial condition)&quot;">​</a></h2><p><strong>[Bổ sung] Phần này mình ghép từ các note trước, sách chưa bàn trong trang 67.</strong> Mình chỉ kiểm tra dignity ở mức <em>domicile, exaltation, detriment, fall</em>. <strong>Chưa kiểm tra triplicity, bound, decan</strong>, nên &quot;peregrine&quot; ở đây nghĩa là &quot;không có 4 dignity chính&quot;, chưa phải kết luận tuyệt đối.</p><h3 id="jackie-la-so-ngay-→-sun-jupiter-saturn-đung-sect-moon-venus-mars-nghich-sect" tabindex="-1">Jackie (lá số ngày → Sun, Jupiter, Saturn đúng sect; Moon, Venus, Mars nghịch sect) <a class="header-anchor" href="#jackie-la-so-ngay-→-sun-jupiter-saturn-đung-sect-moon-venus-mars-nghich-sect" aria-label="Permalink to &quot;Jackie (lá số ngày → Sun, Jupiter, Saturn đúng sect; Moon, Venus, Mars nghịch sect)&quot;">​</a></h3><ul><li><strong>Sun</strong>: ở <strong>domicile (Leo)</strong>, nhà 10 (angular; cách MC khoảng 24° theo độ), đúng sect. Hành tinh mạnh nhất lá số. Sun còn là chủ nhà 10.</li><li><strong>Mercury</strong>: cách Sun chỉ <strong>2.8°</strong>, theo quy tắc cổ điển là <strong>combust/under the beams</strong> (khoảng dưới 8° là thường dùng). Nhưng sách vẫn gọi là &quot;morning phase&quot;. Đây là chỗ gender (phase) và dignity (combust) cho hai kiểu thông tin khác nhau.</li><li><strong>Jupiter</strong> ở Gemini: <strong>detriment</strong>, nhà 8. Jupiter conjunct Venus (cùng cung, orb 12.5°).</li><li><strong>Mars</strong> (chủ Asc): Virgo, nhà 11, peregrine, <strong>nghịch sect</strong> (Mars là hành tinh của đêm). Bị <strong>square</strong> bởi Venus (orb 7.0°), Jupiter (5.6°) và Saturn (9.8°) theo cung.</li><li><strong>Saturn ℞</strong> ở Sagittarius, nhà 2. <strong>Opposition Venus</strong> (orb 2.9°, rất sát), opposition Jupiter (orb 15.4°). <strong>Trine Moon</strong> orb chỉ <strong>1.0°</strong> (rất chặt).</li><li><strong>Moon</strong> ở Aries, nhà 6 (cadent), sextile Venus (3.8°), trine Saturn (1.0°).</li></ul><h3 id="picasso-la-so-đem-→-moon-venus-mars-đung-sect-sun-jupiter-saturn-nghich-sect" tabindex="-1">Picasso (lá số đêm → Moon, Venus, Mars đúng sect; Sun, Jupiter, Saturn nghịch sect) <a class="header-anchor" href="#picasso-la-so-đem-→-moon-venus-mars-đung-sect-sun-jupiter-saturn-nghich-sect" aria-label="Permalink to &quot;Picasso (lá số đêm → Moon, Venus, Mars đúng sect; Sun, Jupiter, Saturn nghịch sect)&quot;">​</a></h3><ul><li><strong>Venus</strong>: <strong>domicile (Libra)</strong>, đúng sect (đêm). Dignity + sect đều tốt, nhưng ở <strong>nhà 3 (cadent)</strong> nên cách thể hiện kín hơn. Sextile Moon rất chặt (orb 3.7°). Square Mars (7.8°).</li><li><strong>Mars</strong>: Cancer = <strong>fall</strong>, nhà 12 (cadent), đúng sect. Sextile Saturn (2.9°), sextile Jupiter, trine Sun và Mercury.</li><li><strong>Sun</strong> ở Scorpio, nhà 4, cách IC khoảng 7.6° (gần như angular theo độ), <strong>nghịch sect</strong>. <strong>Opposition Saturn</strong> (6.8°) và Jupiter (20.9°).</li><li><strong>Mercury</strong> conjunct Sun theo cung (cùng cung Scorpio, nhưng cách nhau 21.5° nên <strong>không</strong> combust). <strong>Opposition Jupiter orb chỉ 0.7°</strong>, gần như chính xác.</li><li><strong>Jupiter và Saturn</strong>: cùng ở Taurus, đều <strong>retrograde</strong>, nhà 10 (whole sign), nghịch sect. Chúng nằm gần như đối diện Sun (159° và 173°), nên retrograde là điều bình thường ở khoảng cách này.</li></ul><blockquote><p><strong>Thận trọng:</strong> đừng dùng các nhận xét này để &quot;giải thích tiểu sử&quot;. Mình nhìn lại cuộc đời một người nổi tiếng rồi tìm dấu hiệu trong lá số thì rất dễ gặp <strong>confirmation bias</strong> (chỉ thấy cái khớp). Sách dùng hai lá số này để <strong>minh họa kỹ thuật</strong>, không phải để chứng minh astrology đúng.</p></blockquote><hr><h2 id="_7-mot-đieu-can-can-than-ve-đao-đuc" tabindex="-1">7. Một điều cần cẩn thận về đạo đức <a class="header-anchor" href="#_7-mot-đieu-can-can-than-ve-đao-đuc" aria-label="Permalink to &quot;7. Một điều cần cẩn thận về đạo đức&quot;">​</a></h2><p>Chương này nói về &quot;giới tính của hành tinh&quot; (năng lượng nam/nữ theo cách người cổ phân loại). Đây là <strong>khung biểu tượng của astrology</strong>, không phải mô tả giới tính, xu hướng tính dục hay bản dạng giới thật của ai. Sách cũng chỉ nêu khả năng, dùng từ &quot;có thể&quot;, và chỉ nói về tông năng lượng. Mình không nên suy ra điều gì về đời tư của Picasso hay Jackie từ bảng này.</p><hr><h2 id="_8-tu-vung" tabindex="-1">8. Từ vựng <a class="header-anchor" href="#_8-tu-vung" aria-label="Permalink to &quot;8. Từ vựng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anh</th><th>Việt gợi ý</th></tr></thead><tbody><tr><td>Example chart</td><td>Lá số ví dụ</td></tr><tr><td>Masculinized feminine</td><td>Nữ bị nam hóa</td></tr><tr><td>Feminized masculine</td><td>Nam bị nữ hóa</td></tr><tr><td>Morning / evening phase</td><td>Pha sáng (đi trước Sun) / pha chiều (đi sau Sun)</td></tr><tr><td>Quadrant</td><td>Góc phần tư (của lá số)</td></tr><tr><td>Combust / under the beams</td><td>Bị Sun &quot;đốt&quot; / dưới tia Sun</td></tr><tr><td>Out of sect</td><td>Nghịch sect</td></tr><tr><td>Chart ruler</td><td>Chủ tinh của lá số (ruler của Asc)</td></tr></tbody></table><hr><h2 id="_9-tu-kiem-tra" tabindex="-1">9. Tự kiểm tra <a class="header-anchor" href="#_9-tu-kiem-tra" aria-label="Permalink to &quot;9. Tự kiểm tra&quot;">​</a></h2><ol><li>Vì sao Picasso được sách nhấn mạnh là &quot;mọi hành tinh ngược giới tính&quot;? (Gợi ý: đếm Bảng ở mục 3.)</li><li>Vì sao Sun của Jackie &quot;nam theo nhà&quot; nhưng &quot;nữ theo độ&quot;?</li><li>Vì sao Mars của Jackie được sách mô tả là &quot;bị làm chậm lại&quot;?</li><li>Vì sao MC của Picasso nằm ở nhà 9 chứ không phải nhà 10 trong whole sign?</li></ol><details><summary>Đáp án gợi ý</summary><ol><li>Cả 5 hành tinh nam (Sun, Mercury, Mars, Jupiter, Saturn) đều ở cung đất/nước, và cả 2 hành tinh nữ (Moon, Venus) đều ở cung lửa/khí.</li><li>Whole sign xếp theo cả cung (nhà 10 = quadrant nam), còn theo độ thì Sun đã ~24° qua MC nên sang quadrant nữ.</li><li>Mars (nam, nhanh, bốc đồng) ở Virgo (cung đất, nữ), nên bị &quot;làm mềm&quot; bằng phân tích và thận trọng. Cũng có thêm phase evening nữ hóa.</li><li>Whole sign gán cả cung Aries (0°–30°) là nhà 9. MC 25° Aries nằm trong cung đó, nên thuộc nhà 9.</li></ol></details><hr><h2 id="_10-nhung-điem-nen-kiem-tra-lai" tabindex="-1">10. Những điểm nên kiểm tra lại <a class="header-anchor" href="#_10-nhung-điem-nen-kiem-tra-lai" aria-label="Permalink to &quot;10. Những điểm nên kiểm tra lại&quot;">​</a></h2><ul><li><strong>Dữ liệu vị trí</strong> mình đọc từ hình. Part of Fortune khớp sách (sai lệch 1&#39;) nên khá an tâm, nhưng bạn nên đối chiếu từng hành tinh với hình trong sách.</li><li><strong>Latitude</strong>: hình không cho, nên điều kiện thứ 4 (nam/nữ theo vĩ độ) <strong>chưa đánh giá</strong>.</li><li><strong>Mercury của Jackie</strong> cách Sun 2.8°: sách gọi &quot;morning phase&quot;. Quy tắc &quot;15–120° mới tính&quot; chỉ là phần nâng cao trong chương. <strong>Phần cơ bản áp dụng cho mọi hành tinh đi trước Sun.</strong> Note Part 2 đã được chỉnh lại cho khớp.</li><li><strong>Dignity</strong> mới kiểm tra 4 mức chính, chưa tính triplicity/bound/decan.</li><li><strong>Cột &quot;đọc ra&quot; ở mục 5</strong> là cách cân của mình, sách chưa có công thức.</li><li><strong>Aspect ở mục 6</strong> xác định theo cung (whole sign: cách 2, 3, 4, 6 cung), còn &quot;orb&quot; là độ lệch thực so với góc chuẩn. Hai thứ này là hai phép tính khác nhau; mình ghi cả hai.</li></ul>',91)])])}const S=t(l,[["render",m]]);export{y as __pageData,S as default};
